glsl3.vert:
precision highp float;
uniform CCGlobal {
  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;
  vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_screenScale;
};
uniform CCLocal {
  mat4 cc_matWorld;
  mat4 cc_matWorldIT;
};
in vec3 a_position;
in vec4 a_color;
out vec4 v_color;
#if USE_TEXTURE
in vec2 a_uv0;
out vec2 v_uv0;
#endif
void main () {
  vec4 pos = vec4(a_position, 1);
  #if CC_USE_MODEL
  pos = cc_matViewProj * cc_matWorld * pos;
  #else
  pos = cc_matViewProj * pos;
  #endif
  #if USE_TEXTURE
  v_uv0 = a_uv0;
  #endif
  v_color = a_color;
  gl_Position = pos;
}

glsl3.frag:
precision lowp float;
uniform CCGlobal {
  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;
  vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_screenScale;
};
#if USE_ALPHA_TEST
  uniform ALPHA_TEST {
    float alphaThreshold;
  };
#endif
in vec4 v_color;
#if USE_TEXTURE
in vec2 v_uv0;
uniform sampler2D texture;
uniform sampler2D texture0;
uniform Const
{
  float u_time;
};
#endif
const float T_TRAN = 1.;
const float T_INTR = 1.;
const float T_PADN = 1.;
const float T_TOTL = ((1. * T_TRAN) + T_INTR + T_PADN);
void main()
{
    float t = mod(u_time, T_TOTL);
    float ts0 =       T_TRAN;
    float ts1 = ts0 + T_INTR;
    float ts2 = ts1 + T_TRAN;
    if(t < ts0) t = t / ts0;
    else if (t < ts1) t = 1.;
    else if (t < ts2) t = 1. - ((t - ts1) / (ts2-ts1));
    else              t = 0.;
    vec4 tex0 = texture(texture, v_uv0);
    vec4 tex1 = texture(texture0, v_uv0);
    vec3 r = mix(tex0.rgb, tex1.rgb, t);
    float a = mix(tex0.a,tex1.a,t);
    gl_FragColor = vec4(r,a);
}

glsl1.vert:
precision highp float;
uniform mat4 cc_matViewProj;
uniform mat4 cc_matWorld;
attribute vec3 a_position;
attribute vec4 a_color;
varying vec4 v_color;
#if USE_TEXTURE
attribute vec2 a_uv0;
varying vec2 v_uv0;
#endif
void main () {
  vec4 pos = vec4(a_position, 1);
  #if CC_USE_MODEL
  pos = cc_matViewProj * cc_matWorld * pos;
  #else
  pos = cc_matViewProj * pos;
  #endif
  #if USE_TEXTURE
  v_uv0 = a_uv0;
  #endif
  v_color = a_color;
  gl_Position = pos;
}

glsl1.frag:
precision lowp float;
#if USE_ALPHA_TEST
#endif
varying vec4 v_color;
#if USE_TEXTURE
varying vec2 v_uv0;
uniform sampler2D texture;
uniform sampler2D texture0;
uniform float u_time;
#endif
const float T_TRAN = 1.;
const float T_INTR = 1.;
const float T_PADN = 1.;
const float T_TOTL = ((1. * T_TRAN) + T_INTR + T_PADN);
void main()
{
    float t = mod(u_time, T_TOTL);
    float ts0 =       T_TRAN;
    float ts1 = ts0 + T_INTR;
    float ts2 = ts1 + T_TRAN;
    if(t < ts0) t = t / ts0;
    else if (t < ts1) t = 1.;
    else if (t < ts2) t = 1. - ((t - ts1) / (ts2-ts1));
    else              t = 0.;
    vec4 tex0 = texture2D(texture, v_uv0);
    vec4 tex1 = texture2D(texture0, v_uv0);
    vec3 r = mix(tex0.rgb, tex1.rgb, t);
    float a = mix(tex0.a,tex1.a,t);
    gl_FragColor = vec4(r,a);
}
